// Charges for part of a billing period.






































/** Rounds half away from zero, in cents. */
export function prorate(cents: number, days: number, periodDays: number) {
  if (periodDays <= 0) throw new Error("empty period");
  return Math.round((cents * days) / periodDays);
}

export const MIN_CHARGE_CENTS = 50;

